/**
 * MaroQuiz — soundtrack builder.
 *
 * Mixes the whole soundtrack in Node and writes ONE stereo WAV file:
 *   - the background music (generated by music.js, or your own music.wav),
 *     quieter while questions type and tick, louder on reveals
 *   - every sound effect at its exact time, with small pitch variations so
 *     repeated sounds never feel robotic
 *   - keyboard clicks for each typed question, one click per letter
 *   - a heartbeat and a soft riser in the last seconds of each countdown
 *
 * FFmpeg then only has to attach this WAV to the video, so the sound no
 * longer depends on which FFmpeg version or filters you have installed.
 */

const fs = require('node:fs');
const { generateMusic } = require('./music');

const RATE = 48000;

// ---------- WAV reading ----------
// Supports PCM 8/16/24/32-bit and 32/64-bit float, any channel count and
// any sample rate (resampled to 48 kHz), so you can drop in your own sounds.
function readWav(file) {
  const buf = fs.readFileSync(file);
  if (buf.toString('ascii', 0, 4) !== 'RIFF' || buf.toString('ascii', 8, 12) !== 'WAVE') {
    throw new Error(`${file} is not a WAV file. Convert it with: ffmpeg -i input -ar 48000 output.wav`);
  }
  let fmt = null;
  let data = null;
  let pos = 12;
  while (pos + 8 <= buf.length) {
    const id = buf.toString('ascii', pos, pos + 4);
    const size = buf.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === 'fmt ') {
      let format = buf.readUInt16LE(body);
      if (format === 0xfffe && size >= 26) format = buf.readUInt16LE(body + 24); // WAVE_FORMAT_EXTENSIBLE
      fmt = { format, channels: buf.readUInt16LE(body + 2), rate: buf.readUInt32LE(body + 4), bits: buf.readUInt16LE(body + 14) };
    } else if (id === 'data') {
      data = buf.subarray(body, Math.min(body + size, buf.length));
    }
    pos = body + size + (size % 2);
  }
  if (!fmt || !data) throw new Error(`${file}: missing fmt or data chunk.`);

  const { format, channels, bits } = fmt;
  const bytes = bits / 8;
  const frames = Math.floor(data.length / (bytes * channels));
  const read = (offset) => {
    if (format === 3) return bits === 64 ? data.readDoubleLE(offset) : data.readFloatLE(offset);
    if (bits === 8) return (data.readUInt8(offset) - 128) / 128;
    if (bits === 16) return data.readInt16LE(offset) / 32768;
    if (bits === 24) return data.readIntLE(offset, 3) / 8388608;
    if (bits === 32) return data.readInt32LE(offset) / 2147483648;
    throw new Error(`${file}: unsupported ${bits}-bit audio.`);
  };

  const left = new Float32Array(frames);
  const right = new Float32Array(frames);
  for (let i = 0; i < frames; i++) {
    const base = i * bytes * channels;
    const l = read(base);
    const r = channels > 1 ? read(base + bytes) : l;
    left[i] = l;
    right[i] = r;
  }
  return fmt.rate === RATE ? { left, right } : { left: resample(left, fmt.rate), right: resample(right, fmt.rate) };
}

function resample(input, fromRate) {
  const ratio = fromRate / RATE;
  const out = new Float32Array(Math.floor(input.length / ratio));
  for (let i = 0; i < out.length; i++) {
    const x = i * ratio;
    const i0 = Math.floor(x);
    const i1 = Math.min(i0 + 1, input.length - 1);
    out[i] = input[i0] + (input[i1] - input[i0]) * (x - i0);
  }
  return out;
}

// ---------- keyboard clicks ----------
function addTyping(mix, startSec, durationSec, cps, gain = 0.9) {
  const period = 1 / cps;
  const start = Math.round(startSec * RATE);
  const n = Math.round(durationSec * RATE);
  let seed = 1234567 + start;
  const rand = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  // one-pole high-pass (~450 Hz) so the clicks sound crisp, not thumpy
  const hpA = Math.exp(-2 * Math.PI * 450 / RATE);
  let prevIn = 0;
  let prevOut = 0;
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    const k = Math.floor(t / period);
    const local = t - k * period;
    const accent = 0.75 + 0.25 * Math.sin(12.9898 * k);
    const raw = (0.9 * (rand() - 0.5) + 0.35 * Math.sin(2 * Math.PI * 2900 * t)) * Math.exp(-330 * local) * accent;
    const hp = hpA * (prevOut + raw - prevIn);
    prevIn = raw;
    prevOut = hp;
    const idx = start + i;
    if (idx >= mix.left.length) break;
    mix.left[idx] += hp * gain;
    mix.right[idx] += hp * gain;
  }
}

function addSound(mix, sound, startSec, gain = 1, rate = 1) {
  const start = Math.round(startSec * RATE);
  const len = Math.min(Math.floor(sound.left.length / rate), mix.left.length - start);
  for (let i = 0; i < len; i++) {
    const x = i * rate;
    const i0 = Math.floor(x);
    const i1 = Math.min(i0 + 1, sound.left.length - 1);
    const fr = x - i0;
    mix.left[start + i] += (sound.left[i0] + (sound.left[i1] - sound.left[i0]) * fr) * gain;
    mix.right[start + i] += (sound.right[i0] + (sound.right[i1] - sound.right[i0]) * fr) * gain;
  }
}

// two low thumps, like a heartbeat
function addHeartbeat(mix, startSec, gain = 0.55) {
  for (const [off, amp] of [[0, 1], [0.24, 0.7]]) {
    const start = Math.round((startSec + off) * RATE);
    let ph = 0;
    for (let i = 0; i < 0.3 * RATE; i++) {
      const t = i / RATE;
      ph += 2 * Math.PI * (52 + 30 * Math.exp(-t * 25)) / RATE;
      const v = Math.sin(ph) * Math.exp(-t * 11) * Math.min(1, t / 0.004) * amp * gain;
      const idx = start + i;
      if (idx >= mix.left.length) break;
      mix.left[idx] += v; mix.right[idx] += v;
    }
  }
}

// soft rising swell that builds tension right before the reveal
function addRiser(mix, startSec, durationSec, gain = 0.12) {
  const start = Math.round(startSec * RATE);
  const len = Math.round(durationSec * RATE);
  let seed = 99 + start;
  const rand = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  let lp = 0;
  let ph = 0;
  for (let i = 0; i < len; i++) {
    const k = i / len;
    const cutoff = 0.02 + 0.25 * k * k;
    lp += cutoff * ((rand() * 2 - 1) - lp);
    ph += 2 * Math.PI * (220 + 440 * k * k) / RATE;
    const env = k * k * (k > 0.97 ? (1 - k) / 0.03 : 1);
    const v = (lp * 0.9 + Math.sin(ph) * 0.25) * env * gain;
    const idx = start + i;
    if (idx >= mix.left.length) break;
    mix.left[idx] += v * 0.9; mix.right[idx] += v * 1.1;
  }
}

// soft limiter: transparent below 0.8, smoothly caps peaks at 1.0
function limit(x) {
  const a = Math.abs(x);
  if (a <= 0.8) return x;
  return Math.sign(x) * (0.8 + 0.2 * Math.tanh((a - 0.8) / 0.2));
}

function writeWav(file, mix) {
  const frames = mix.left.length;
  const buf = Buffer.alloc(44 + frames * 4);
  buf.write('RIFF', 0); buf.writeUInt32LE(36 + frames * 4, 4); buf.write('WAVE', 8);
  buf.write('fmt ', 12); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(2, 22);
  buf.writeUInt32LE(RATE, 24); buf.writeUInt32LE(RATE * 4, 28); buf.writeUInt16LE(4, 32); buf.writeUInt16LE(16, 34);
  buf.write('data', 36); buf.writeUInt32LE(frames * 4, 40);
  let peak = 0;
  let sumSq = 0;
  for (let i = 0; i < frames; i++) {
    const l = limit(mix.left[i]);
    const r = limit(mix.right[i]);
    peak = Math.max(peak, Math.abs(l), Math.abs(r));
    sumSq += l * l;
    buf.writeInt16LE(Math.round(Math.max(-1, Math.min(1, l)) * 32767), 44 + i * 4);
    buf.writeInt16LE(Math.round(Math.max(-1, Math.min(1, r)) * 32767), 46 + i * 4);
  }
  fs.writeFileSync(file, buf);
  const db = (v) => (v > 0 ? 20 * Math.log10(v) : -Infinity);
  return { peakDb: db(peak), rmsDb: db(Math.sqrt(sumSq / Math.max(1, frames))) };
}

// loops your own music file under the video, with the same ducking
function loopMusicFile(file, duration, sections) {
  const src = readWav(file);
  const n = Math.ceil(duration * RATE);
  const left = new Float32Array(n);
  const right = new Float32Array(n);
  const DUCK = { type: 0.5, countdown: 0.55, milestone: 0.8, reveal: 0.9 };
  let duck = 0.9;
  const smooth = 1 - Math.exp(-1 / (0.18 * RATE));
  let si = 0;
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    while (si < sections.length - 1 && t >= sections[si].end) si++;
    duck += smooth * ((DUCK[sections[si]?.duck] ?? 0.9) - duck);
    const k = 0.5 * duck * Math.min(1, t / 1.2) * Math.max(0, Math.min(1, (duration - t) / 2.8));
    const j = i % src.left.length;
    left[i] = src.left[j] * k;
    right[i] = src.right[j] * k;
  }
  return { left, right };
}

/**
 * @param {object} opts
 * @param {Array} opts.events     [{ time, file }] where file is a WAV path, or
 *                                { typing: {duration, cps} }, { heartbeat: true },
 *                                { riser: {duration} }; add vary: true for pitch variety
 * @param {Array} opts.sections   [{ start, end, kind, duck }] — the video's structure
 * @param {string|null} opts.musicFile  your own music WAV, or null to generate music
 * @param {number} opts.duration  video length in seconds
 * @param {string} opts.outFile   where to write the stereo 48 kHz WAV
 * @returns {{peakDb:number, rmsDb:number, music:string}}
 */
function buildSoundtrack({ events, sections, musicFile, duration, outFile }) {
  const music = musicFile ? loopMusicFile(musicFile, duration, sections) : generateMusic({ duration, sections });
  const mix = { left: music.left, right: music.right };
  const cache = new Map();
  const load = (file) => {
    if (!cache.has(file)) cache.set(file, readWav(file));
    return cache.get(file);
  };

  events.forEach((ev, i) => {
    const f = ev.file;
    if (typeof f === 'string') {
      // small, repeatable pitch changes (±5%) for sounds that repeat a lot
      const rate = ev.vary ? 1 + (Math.sin(i * 12.9898) * 43758.5453 % 1) * 0.05 : 1;
      addSound(mix, load(f), ev.time, ev.gain ?? 1, rate);
    } else if (f && f.typing) addTyping(mix, ev.time, f.typing.duration, f.typing.cps);
    else if (f && f.heartbeat) addHeartbeat(mix, ev.time);
    else if (f && f.riser) addRiser(mix, ev.time, f.riser.duration);
  });
  const levels = writeWav(outFile, mix);
  return { ...levels, music: musicFile ? 'your music.wav' : 'generated' };
}

module.exports = { buildSoundtrack, readWav };
